/**
 * Homepage copy for the 2026-09 redesign.
 *
 * Deliberately a typed module rather than next-intl messages for now: the copy is
 * still being reviewed, and extracting it to `messages/en.json` + `messages/vi.json`
 * before it settles means doing that work twice. Extraction is mechanical once the
 * wording is signed off.
 *
 * **Every number in this file is measured, not marketing.** They come from
 * `docs/voi-results.md`, regenerated by
 * `pnpm --filter @pulse/road-runner voi:spike -- apps/api/road-runner/fixtures/voi-laptops.json`.
 * Nothing here may state a conversion, revenue or uplift figure: ODIN/demo/DEMO.md §1.1.
 */

/** The laptop shelf, 216 products. Both rankings, because their disagreement is the thesis. */
export interface AttributeRow {
  attribute: string;
  /** Key into `storyUi`, so the rendered label follows the locale. */
  key: "screenSize" | "memory" | "processor" | "storage";
  missing: number;
  /** Bits the catalogue loses by not recording this field everywhere. */
  gap: number;
  /** Rank by that gap, which is what coverage-led tooling would tell you. */
  coverageRank: number;
  /** Rank by decision value: how much it moves the questions shoppers actually ask. */
  decisionRank: number;
  /** How many of the 32 stated buying requirements mention it at all. */
  tasks: number;
}

